protocol Clock { func now() throws -> Date }

final class ConfigurableClock: Clock {
    var instant = Date(timeIntervalSince1970: 0)
    var failure: Error?
    private(set) var callCount = 0
    func now() throws -> Date {
        callCount += 1
        if let failure { throw failure }
        return instant
    }
}

